from _lib import *
MM="Manuel des Monstres 5e (2014), entrée « %s »"
PHB="Manuel des Joueurs 5e (2014), "
D="Dans D&D 5e, "
C("mar-001",1,D+"quel monstre géant à tentacules coule les navires ?",["Le kraken","La tortue-dragon","Le marid","L’hydre"],"Le kraken (FP 23) est un monstre titanesque des abysses ; il saisit les navires, les brise et commande à la foudre. La tortue-dragon, elle, attaque à la morsure et par un souffle de vapeur.",MM%"Kraken")
C("mar-002",2,D+"quel peuple amphibie à l’allure de requin-humanoïde hait les elfes marins ?",["Les sahuagins","Les locathahs","Les tritons","Les kuo-toas"],"Les sahuagins vivent en cités sous-marines, vénèrent un dieu requin et considèrent les elfes marins comme leurs pires ennemis ; les tritons, eux, sont plutôt des gardiens des profondeurs.",MM%"Sahuagin")
C("mar-003",2,D+"que déclenche l’odeur du sang chez un sahuagin ?",["Une frénésie sanguinaire (avantage au corps à corps sur une cible blessée)","Une invisibilité temporaire","Une téléportation vers sa cité","Un dédoublement en deux sahuagins"],"Le trait Frénésie sanguinaire (Blood Frenzy) donne l’avantage aux attaques de corps à corps contre une créature qui n’a pas tous ses points de vie.",MM%"Sahuagin")
C("mar-004",2,D+"quelle guenaude des mers peut réduire à 0 PV une créature effrayée d’un simple regard ?",["La guenaude des mers (sea hag)","La guenaude verte","La guenaude nocturne","La banshee"],"Le regard de mort (Death Glare) de la guenaude des mers vise une créature effrayée dans les 9 m ; en cas d’échec au jet de Sagesse, elle tombe à 0 PV. C’est une fée, pas un humanoïde.",MM%"Guenaude des mers")
C("mar-005",2,D+"quelle créature aquatique crache de la vapeur brûlante ?",["La tortue-dragon","Le kraken","L’aboleth","Le scrag"],"La tortue-dragon (FP 17) est un véritable dragon : son souffle de vapeur frappe en cône de 18 m et inflige 15d8 dégâts de feu.",MM%"Tortue-dragon")
C("mar-006",1,D+"quel peuple jouable a pour traits « Émissaire de la mer » et « Gardiens des profondeurs » ?",["Les tritons","Les tieffelins","Les drakéides","Les gnomes"],"Les tritons gardent les profondeurs océaniques contre les monstres des abysses ; ils respirent à l’air comme sous l’eau et parlent aux animaux marins.",D+"Guide de Volo des monstres (2016), chap. 3 « Triton »")
C("mar-007",2,D+"quelle lignée de génasi est liée à l’eau et respire sous l’eau ?",["Les génasi de l’eau","Les génasi du feu","Les génasi de l’air","Les génasi de la terre"],"Les génasi de l’eau sont amphibies, résistent à l’acide et peuvent lancer Création ou destruction d’eau ; ils nagent à 9 m.",D+"Elemental Evil Player’s Companion (2015), « Genasi »")
C("mar-008",2,D+"quel sort de niveau 3 permet à dix créatures de respirer sous l’eau pendant 24 heures ?",["Respiration aquatique","Marche sur l’eau","Forme gazeuse","Contrôle de l’eau"],"Respiration aquatique (Water Breathing) est un rituel de niveau 3 : jusqu’à dix créatures consentantes respirent sous l’eau pendant 24 heures.",PHB+"chap. 11 « Sorts », Respiration aquatique ; SRD 5.1, « Water Breathing »")
C("mar-009",3,D+"quel sort de niveau 4 permet de fendre, soulever ou détourner l’eau dans un cube de 30 m d’arête ?",["Contrôle de l’eau","Tsunami","Façonnage de l’eau","Création ou destruction d’eau"],"Contrôle de l’eau (Control Water) agit dans un cube de 100 pieds (30 m) pendant 10 minutes de concentration ; Tsunami est un sort de niveau 8 bien plus vaste.",PHB+"chap. 11 « Sorts », Contrôle de l’eau")
C("mar-010",3,D+"quel sort de niveau 8 fait surgir un mur d’eau de 90 m de long ?",["Tsunami","Contrôle de l’eau","Tempête de vengeance","Maelström"],"Tsunami (niveau 8, druide) crée un mur d’eau de 90 m de long, de 90 m de haut et de 15 m d’épaisseur, qui balaie le terrain pendant 6 rounds.",PHB+"chap. 11 « Sorts », Tsunami")
C("mar-011",2,D+"quel objet magique permet de commander aux bêtes capables de nager ?",["Le trident de commandement des poissons","L’anneau de nage","La cape de la raie manta","Les bottes de lévitation"],"Le trident de commandement des poissons (3 charges) lance Domination de bête sur une bête dotée d’une vitesse de nage.",D+"Guide du Maître (2014), chap. 7 « Trésors », objets magiques")
C("mar-012",2,D+"quel objet magique donne une vitesse de nage de 12 m (40 pieds) ?",["L’anneau de nage","La cape de la raie manta","Le trident de commandement des poissons","Les bottes elfiques"],"L’anneau de nage (swim speed 40 ft) est un objet peu courant ; la cape de la raie manta, elle, donne 18 m de nage et la respiration sous l’eau.",D+"Guide du Maître (2014), chap. 7 « Trésors »")
C("mar-013",3,"Dans les Royaumes Oubliés (D&D), quelle déesse malveillante règne sur les mers et exige des sacrifices des marins ?",["Umberlee","Séluné","Tymora","Mystra"],"Umberlee, la « Reine de la tempête », chaotique mauvaise, est apaisée par les marins qui lui jettent des offrandes avant de prendre la mer.",D+"Sword Coast Adventurer’s Guide (2015), panthéon des Royaumes")
C("mar-014",3,"Dans les Royaumes Oubliés (D&D), quel dieu elfique patronne les océans et les elfes marins ?",["Deep Sashelas","Corellon Larethian","Sehanine Moonbow","Erevan Ilesere"],"Deep Sashelas, dieu elfe des océans, de la beauté et de la connaissance, est vénéré surtout par les elfes marins.",D+"Forgotten Realms Wiki, article « Deep Sashelas » ; Mordenkainen’s Tome of Foes (2018), « Elfes marins »")
C("mar-015",3,"Dans les Royaumes Oubliés (D&D), quel dieu requin est vénéré par les sahuagins ?",["Sekolah","Umberlee","Deep Sashelas","Valkur"],"Sekolah, le Dieu requin, est le patron des sahuagins ; il leur inspire sa cruauté et leur désir de dominer les mers.",D+"Forgotten Realms Wiki, article « Sekolah »")
C("mar-016",2,D+"comment appelle-t-on l’ogre aquatique des mers et des côtes ?",["Le merrow","Le scrag","Le sahuagin","Le kuo-toa"],"Le merrow est un ogre amphibie aux écailles verdâtres, qui chasse les marins près des côtes.",MM%"Merrow")
C("mar-017",3,D+"quel troll aquatique régénère tant qu’il se trouve dans l’eau ?",["Le scrag","Le merrow","L’hydre","Le marid"],"Le scrag (FP 5) regagne 10 PV par tour tant qu’il est dans l’eau, sauf s’il subit de l’acide ou du feu ; sa régénération ne fonctionne pas hors de l’eau.",MM%"Scrag (troll)")
C("mar-018",3,D+"quel génie aquatique règne sur les mers et les tempêtes ?",["Le marid","Le djinn","L’éfrit","Le dao"],"Le marid (FP 11) est le génie de l’eau : il vient du Plan élémentaire de l’Eau, qui contient aussi des mers infinies.",MM%"Marid")
C("mar-019",2,D+"quel petit humanoïde à écailles de poisson vit en tribus sous-marines ?",["Le locathah","Le kobold","Le gnoll","Le yuan-ti"],"Les locathahs sont de petits humanoïdes marins (FP 1/2), pacifiques et plutôt discrets ; ils vivent en communautés tribales et ont un bouclier d’écailles.",MM%"Locathah")
C("mar-020",3,D+"quelle aberration aquatique, plus ancienne que les dieux, asservit les esprits ?",["L’aboleth","Le kraken","Le marid","Le scrag"],"L’aboleth (FP 10) vit dans les lacs et les mers souterrains ; ses pouvoirs de domination en font le maître d’esclaves aquatiques.",MM%"Aboleth")
C("mar-021",3,D+"quel dragon métallique, aimant les côtes, crache un éclair ?",["Le dragon de bronze","Le dragon d’argent","Le dragon d’or","Le dragon de cuivre"],"Le dragon de bronze hante côtes et falaises ; il crache un souffle de foudre en ligne et un souffle de répulsion.",MM%"Dragon de bronze")
C("mar-022",1,D+"quelle créature marine peut libérer un nuage d’encre pour s’enfuir ?",["La pieuvre géante","Le requin géant","L’orque (épaulard)","L’hippocampe géant"],"La pieuvre géante (FP 1) possède Nuage d’encre : une zone obscurcie de 6 m de rayon qui lui permet de fuir.",MM%"Pieuvre géante")
C("mar-023",2,D+"que sont les quippers ?",["De petits poissons carnassiers qui attaquent en banc","Des serpents de mer géants","Des méduses venimeuses","Des crabes géants"],"Les quippers (FP 0) sont des piranhas à la morsure faible mais en frénésie sanguinaire ; un banc (essaim de quippers) est dangereux pour un aventurier blessé.",MM%"Quipper")
C("mar-024",3,D+"quel handicap subit un personnage sans vitesse de nage qui attaque au corps à corps sous l’eau ?",["Un désavantage, sauf avec dague, javeline, épée courte, lance ou trident","Un bonus de +2 au toucher","Aucun handicap","Il ne peut pas attaquer du tout"],"Seules les armes à pointe courte (dague, javeline, épée courte, lance, trident) évitent le désavantage ; les attaques à distance ratent automatiquement au-delà de la portée normale.",PHB+"chap. 9 « Combattre », Combat sous-marin")
C("mar-025",3,D+"combien de temps un personnage peut-il retenir son souffle ?",["1 minute + son modificateur de Constitution (30 secondes minimum)","10 minutes","Autant de rounds que sa Force","30 minutes"],"Ensuite il peut survivre un nombre de rounds égal à son modificateur de Constitution (minimum 1) avant de tomber à 0 PV et de se noyer.",PHB+"chap. 8 « Aventures », Suffocation")
C("mar-026",3,D+"quelle résistance gagne une créature entièrement immergée ?",["La résistance aux dégâts de feu","La résistance au froid","La résistance à la foudre","La résistance au poison"],"Les créatures et objets entièrement immergés résistent au feu, ce qui rend les boules de feu moins efficaces sous l’eau.",PHB+"chap. 9 « Combattre », Combat sous-marin")
C("mar-027",2,D+"quel supplément de 2019 est consacré aux aventures maritimes et aux règles de navires ?",["Ghosts of Saltmarsh","Curse of Strahd","Tomb of Annihilation","Waterdeep : Dragon Heist"],"Ghosts of Saltmarsh (2019) réunit sept aventures nautiques et des règles de combat naval, de bateaux et de rencontres en mer.",D+"Ghosts of Saltmarsh (2019), introduction")
C("mar-028",2,D+"quel géant vit souvent dans les profondeurs marines ou sur des îles battues par la tempête ?",["Le géant des tempêtes","Le géant des collines","Le géant du feu","Le géant des nuages"],"Les géants des tempêtes bâtissent leurs citadelles au fond des mers ou sur de hautes falaises ; ils respirent sous l’eau et contrôlent la foudre.",MM%"Géant des tempêtes")
C("mar-029",3,D+"quel livre introduit les tritons comme peuple jouable ?",["Le Guide de Volo des monstres (2016)","Le Manuel des Joueurs (2014)","Le Guide de Xanathar (2017)","Tasha et le chaudron de tout (2020)"],"Les tritons apparaissent dans le chapitre « Aventuriers monstrueux » du Guide de Volo des monstres (2016), à côté des aasimars, kenkus ou tabaxis.",D+"Volo’s Guide to Monsters (2016), chap. 3")
C("mar-030",2,D+"quel élément le kraken invoque-t-il pour frapper à distance ?",["La foudre","Le feu","L’acide","Le froid"],"Le kraken possède une action légendaire de foudre (Lightning Storm) qui frappe jusqu’à trois cibles ; il génère aussi des tempêtes autour de son repaire.",MM%"Kraken")
V("mar-031",2,D+"le kraken a un facteur de puissance de 23.",True,"Vrai : FP 23, il est parmi les monstres les plus puissants hors dragons anciens, avec 472 PV et une CA de 18.",MM%"Kraken")
V("mar-032",1,D+"les sahuagins haïssent les elfes marins.",True,"Vrai : c’est l’ennemi héréditaire des sahuagins, qui détestent les elfes marins et les tritons.",MM%"Sahuagin")
V("mar-033",3,D+"la tortue-dragon est un véritable dragon.",True,"Vrai : son type de créature est « dragon », malgré son aspect de tortue ; elle est neutre et peut avoir une affinité avec les dragons métalliques.",MM%"Tortue-dragon")
V("mar-034",3,D+"la guenaude des mers est un humanoïde.",False,"Faux : toutes les guenaudes sont des fées (fey), pas des humanoïdes.",MM%"Guenaude des mers")
V("mar-035",2,D+"le triton peut respirer à l’air libre comme sous l’eau.",True,"Vrai : les tritons sont amphibies, ce qui leur permet de remonter à la surface sans difficulté.",D+"Guide de Volo des monstres (2016), chap. 3 « Triton »")
V("mar-036",3,D+"une créature entièrement immergée résiste aux dégâts de feu.",True,"Vrai : c’est une règle de combat sous-marin du Manuel des Joueurs.",PHB+"chap. 9 « Combattre », Combat sous-marin")
V("mar-037",2,D+"le sort Respiration aquatique dure 1 heure.",False,"Faux : sa durée est de 24 heures.",PHB+"chap. 11 « Sorts », Respiration aquatique")
V("mar-038",2,D+"le sort Marche sur l’eau permet de respirer sous l’eau.",False,"Faux : Marche sur l’eau (Water Walk) permet de marcher sur les liquides, c’est Respiration aquatique qui permet de respirer sous l’eau.",PHB+"chap. 11 « Sorts », Marche sur l’eau")
V("mar-039",2,D+"le marid est un génie de l’eau.",True,"Vrai : le marid appartient à la famille des génies élémentaires, avec le djinn (air), l’éfrit (feu) et le dao (terre).",MM%"Marid")
V("mar-040",3,D+"le scrag régénère tant qu’il est dans l’eau.",True,"Vrai : 10 PV par tour dans l’eau, sauf après un dégât d’acide ou de feu.",MM%"Scrag (troll)")
V("mar-041",1,D+"la pieuvre géante peut lâcher un nuage d’encre.",True,"Vrai : une fois par repos court ou long, elle s’échappe grâce à un nuage d’encre.",MM%"Pieuvre géante")
V("mar-042",1,D+"le locathah est un monstre des déserts.",False,"Faux : c’est un humanoïde aquatique, qui vit sous l’eau.",MM%"Locathah")
V("mar-043",2,D+"le dragon de bronze crache un souffle de foudre.",True,"Vrai : en ligne de 27 m, avec 12d10 dégâts de foudre pour un adulte.",MM%"Dragon de bronze")
V("mar-044",2,D+"le dragon de bronze crache un souffle d’acide.",False,"Faux : l’acide est le souffle du dragon noir et du dragon de cuivre.",MM%"Dragon de bronze")
V("mar-045",2,"Dans les Royaumes Oubliés (D&D), Umberlee est la déesse des mers.",True,"Vrai : c’est la déesse de la mer et des tempêtes, chaotique mauvaise.",D+"Sword Coast Adventurer’s Guide (2015), panthéon des Royaumes")
V("mar-046",3,"Dans les Royaumes Oubliés (D&D), Sekolah est le dieu des sahuagins.",True,"Vrai : le Dieu requin est leur patron principal.",D+"Forgotten Realms Wiki, article « Sekolah »")
V("mar-047",2,D+"les quippers sont de gros poissons solitaires.",False,"Faux : ce sont de petits poissons qui attaquent en banc.",MM%"Quipper")
V("mar-048",3,D+"le géant des tempêtes peut vivre au fond des mers.",True,"Vrai : ils respirent sous l’eau et bâtissent des cités sous-marines.",MM%"Géant des tempêtes")
V("mar-049",3,D+"l’anneau de nage donne une vitesse de nage de 18 m.",False,"Faux : 12 m (40 pieds). La cape de la raie manta donne 18 m (60 pieds).",D+"Guide du Maître (2014), chap. 7 « Trésors »")
V("mar-050",3,D+"les tritons font partie du Manuel des Joueurs de 2014.",False,"Faux : ils sont apparus dans le Guide de Volo des monstres (2016).",D+"Volo’s Guide to Monsters (2016), chap. 3")
V("mar-051",2,D+"l’aboleth vit uniquement à la surface, loin de l’eau.",False,"Faux : il vit dans les lacs et mers souterrains.",MM%"Aboleth")
V("mar-052",3,D+"le requin géant a un FP supérieur à celui de la pieuvre géante.",True,"Vrai : FP 5 contre FP 1.",MM%"Requin géant")
