S("mar-058",2,D+"quel est le FP de l’orque (épaulard) ?",0,30,1,"FP",0,3,"FP 3 : 90 PV, un prédateur marin rapide qui chasse en groupe.",MM%"Orque (killer whale)")
S("mar-059",3,D+"quel est le FP de la tortue-dragon ?",0,30,1,"FP",0,17,"FP 17 : 341 PV et un souffle de vapeur dévastateur.",MM%"Tortue-dragon")
