S("mar-063",3,D+"quelle est la vitesse de nage de la tortue-dragon (en pieds) ?",0,120,5,"pieds",0,40,"40 pieds (12 m) à la nage, 20 pieds (6 m) sur terre.",MM%"Tortue-dragon")
S("mar-064",3,D+"combien de points de vie moyens a un sahuagin ?",5,100,1,"PV",0,22,"22 PV (4d8 + 4) : un adversaire modeste, dangereux en nombre.",MM%"Sahuagin")
S("mar-065",2,D+"de quel niveau est le sort Respiration aquatique ?",1,9,1,"niveau",0,3,"Niveau 3, avec le composant matériel d’un roseau ou d’une paille.",PHB+"chap. 11 « Sorts », Respiration aquatique")
S("mar-066",3,D+"combien de créatures peut affecter Respiration aquatique (maximum) ?",1,20,1,"créatures",0,10,"Jusqu’à dix créatures consentantes à portée.",PHB+"chap. 11 « Sorts », Respiration aquatique")
S("mar-067",3,D+"combien d’heures dure le sort Respiration aquatique ?",1,48,1,"heures",0,24,"24 heures : de quoi explorer un récif sans souci.",PHB+"chap. 11 « Sorts », Respiration aquatique")
S("mar-068",2,D+"quelle vitesse de nage donne l’anneau de nage (en pieds) ?",10,100,5,"pieds",0,40,"40 pieds (12 m), soit largement plus que les 30 pieds de marche normale.",D+"Guide du Maître (2014), chap. 7 « Trésors »")
S("mar-069",3,D+"combien de points de vie moyens a un requin géant (à 10 près) ?",20,300,1,"PV",10,126,"126 PV (11d12 + 55).",MM%"Requin géant")
S("mar-070",2,D+"combien de points de vie moyens a une pieuvre géante (à 5 près) ?",10,150,1,"PV",5,52,"52 PV (8d10 + 8).",MM%"Pieuvre géante")
